entities:
{
  name: 'user',
  columns: {
    id: {
      type: 'varchar',
      primary: true
    },
    password: {
      type: 'varchar'
    }
  },
  relations: {
    tags: {
      type: 'one-to-many',
      target: 'userTag',
      cascade: true,
      inverseSide: 'user'
    }
  }
}

{
  name: 'userTag',
  columns: {
    id: {
      type: 'int',
      primary: true,
      generated: true
    },
    name: {
      type: 'varchar',
      foreignKey: {
        target: 'userTagName'
      }
    },
    start: {
      type: 'date',
      nullable: true
    },
    end: {
      type: 'date',
      nullable: true
    }
  },
  relations: {
    user: {
      type: 'many-to-one',
      target: 'user',
      onDelete: 'CASCADE',
      orphanedRowAction: 'delete',
      inverseSide: 'tags'
    }
  }
}

{
  name: 'userTagName',
  columns: {
    id: {
      type: 'varchar',
      primary: true
    }
  }
}
